from pathlib import Path

from electrum import bitcoin, constants
from electrum.blockchain import BlockchainManager, InvalidHeader, deserialize_header
from electrum.transaction import Transaction

from . import ElectrumTestCase

# mainnet blocks 157500 (ASERT + MWEB activation) to 157502, all merge-mined
HEADERS = [bytes.fromhex(h) for h in (
    "",
    "",
    "",
)]


class TestBitcoinOil(ElectrumTestCase):
    def setUp(self):
        super().setUp()
        self.chain = BlockchainManager(headers_dir=Path(self.electrum_path)).get_best_chain()

    def test_connect(self):
        self.assertEqual(157499, constants.net.max_checkpoint())
        for i, raw in enumerate(HEADERS):
            header = deserialize_header(raw, 157500 + i)
            self.assertTrue(self.chain.can_connect(header, check_height=False))
            if i == 0:
                self.assertTrue(self.chain.connect_chunk(315, HEADERS))
        self.assertEqual(157502, self.chain.height())

    def test_reject_bad_pow(self):
        raw = HEADERS[0]
        # the node does not use the parent hash and the coinbase index
        end = len(raw)
        for pos in list(range(80)) + list(range(end - 80, end)):
            bad = bytearray(raw)
            bad[pos] ^= 1
            try:
                header = deserialize_header(bytes(bad), 157500)
            except InvalidHeader:
                continue
            self.assertFalse(self.chain.can_connect(header, check_height=False), msg=pos)
        self.assertFalse(self.chain.can_connect(deserialize_header(raw[:80], 157500), check_height=False))
        with self.assertRaises(InvalidHeader):
            deserialize_header(raw + b"\x00", 157500)

    def test_reject_far_future(self):
        import electrum.blockchain as b
        real = b.time.time
        try:
            b.time.time = lambda: 1795466728 - 4 * 3600
            self.assertFalse(self.chain.can_connect(deserialize_header(HEADERS[0], 157500), check_height=False))
        finally:
            b.time.time = real

    def test_address(self):
        self.assertTrue(bitcoin.is_address("btco1qw508d6qejxtdg4y5r3zarvary0c5xw7k5g2wc6"))
        self.assertFalse(bitcoin.is_address("bc1qw508d6qejxtdg4y5r3zarvary0c5xw7kv8f3t4"))
        self.assertFalse(bitcoin.is_address("14gcRovpkCoGkCNBivQBvw7eso7eiNAbxG"))

    def test_hogex(self):
        # two outputs: the MWEB balance and a peg-out, MWEB flag with a null MWEB part
        outs = ("02" + "00e1f50500000000" + "225820" + "11" * 32 + "0010000000000000" + "160014" + "22" * 20)
        legacy = "02000000" + "01" + "33" * 32 + "00000000" + "00" + "ffffffff" + outs + "00000000"
        hogex = "02000000" + "0008" + "01" + "33" * 32 + "00000000" + "00" + "ffffffff" + outs + "00" + "00000000"
        self.assertEqual(Transaction(legacy).txid(), Transaction(hogex).txid())
        self.assertTrue(Transaction(hogex).is_hogex_tx())
